    if (s == "INK") return pm_menu_view::INK;
    if (s == "GOLD") return pm_menu_view::GOLD;
    if (s == "WARN") return pm_menu_view::WARN;
    if (s == "PURPLE") return pm_menu_view::PURPLE;
