    if (s == "_center") return V::func(f__center);
    if (s == "_picture") return V::func(f__picture);
    if (s == "_backdrop") return V::func(f__backdrop);
    if (s == "_message") return V::func(f__message);
    if (s == "draw_home") return V::func(f_draw_home);
